CREATE TABLE analytics_meta (id INTEGER PRIMARY KEY CHECK(id = 1), initialized INTEGER NOT NULL DEFAULT 0, coverage_from TEXT);
INSERT INTO analytics_meta(id, initialized) VALUES (1, 0);
CREATE TABLE sales_daily (day TEXT PRIMARY KEY, received INTEGER NOT NULL DEFAULT 0, pending INTEGER NOT NULL DEFAULT 0, accepted INTEGER NOT NULL DEFAULT 0, preparing INTEGER NOT NULL DEFAULT 0, dispatched INTEGER NOT NULL DEFAULT 0, completed INTEGER NOT NULL DEFAULT 0, cancelled INTEGER NOT NULL DEFAULT 0, revenue_cents INTEGER NOT NULL DEFAULT 0, drink_completed INTEGER NOT NULL DEFAULT 0, pix_completed INTEGER NOT NULL DEFAULT 0, card_completed INTEGER NOT NULL DEFAULT 0);
CREATE TABLE sales_products_daily (day TEXT NOT NULL, kind TEXT NOT NULL, product_key TEXT NOT NULL, quantity INTEGER NOT NULL, PRIMARY KEY(day, kind, product_key));
CREATE TABLE sales_hourly (day TEXT NOT NULL, hour INTEGER NOT NULL, received INTEGER NOT NULL, PRIMARY KEY(day, hour));
CREATE TABLE management_reports (period TEXT PRIMARY KEY, generated_at TEXT NOT NULL, payload_json TEXT NOT NULL);
CREATE TRIGGER sales_orders_insert AFTER INSERT ON orders BEGIN
INSERT INTO sales_daily (day, received, pending, accepted, preparing, dispatched, completed, cancelled, revenue_cents, drink_completed, pix_completed, card_completed) VALUES (date(NEW.created_at, '-3 hours'), 1, (NEW.status = 'pending'), (NEW.status = 'accepted'), (NEW.status = 'preparing'), (NEW.status = 'dispatched'), (NEW.status = 'completed'), (NEW.status = 'cancelled'), CASE WHEN NEW.status = 'completed' THEN NEW.total_cents ELSE 0 END, (NEW.status = 'completed' AND EXISTS (SELECT 1 FROM json_each(NEW.items_json, '$.drinks') WHERE CAST(value AS INTEGER) > 0)), (NEW.status = 'completed' AND json_extract(NEW.customer_json, '$.payment') = 'pix'), (NEW.status = 'completed' AND json_extract(NEW.customer_json, '$.payment') = 'card')) ON CONFLICT(day) DO UPDATE SET received = received + excluded.received, pending = pending + excluded.pending, accepted = accepted + excluded.accepted, preparing = preparing + excluded.preparing, dispatched = dispatched + excluded.dispatched, completed = completed + excluded.completed, cancelled = cancelled + excluded.cancelled, revenue_cents = revenue_cents + excluded.revenue_cents, drink_completed = drink_completed + excluded.drink_completed, pix_completed = pix_completed + excluded.pix_completed, card_completed = card_completed + excluded.card_completed;
INSERT INTO sales_hourly(day, hour, received) VALUES (date(NEW.created_at, '-3 hours'), CAST(strftime('%H', NEW.created_at, '-3 hours') AS INTEGER), 1) ON CONFLICT(day, hour) DO UPDATE SET received = received + 1;
INSERT INTO sales_products_daily(day, kind, product_key, quantity)
SELECT date(NEW.created_at, '-3 hours'), 'pancake', json_object('filling', json_extract(p.value, '$.filling'), 'dough', json_extract(p.value, '$.dough'), 'sauce', json_extract(p.value, '$.sauce'), 'extras', json(COALESCE(json_extract(p.value, '$.extras'), '[]'))), 1 * CAST(json_extract(p.value, '$.qty') AS INTEGER) FROM json_each(NEW.items_json, '$.pancakes') p WHERE NEW.status = 'completed'
ON CONFLICT(day, kind, product_key) DO UPDATE SET quantity = quantity + excluded.quantity;
INSERT INTO sales_products_daily(day, kind, product_key, quantity)
SELECT date(NEW.created_at, '-3 hours'), 'drink', p.key, 1 * CAST(p.value AS INTEGER) FROM json_each(NEW.items_json, '$.drinks') p WHERE NEW.status = 'completed' AND CAST(p.value AS INTEGER) > 0
ON CONFLICT(day, kind, product_key) DO UPDATE SET quantity = quantity + excluded.quantity;
END;
CREATE TRIGGER sales_orders_status AFTER UPDATE OF status ON orders WHEN OLD.status <> NEW.status BEGIN
INSERT INTO sales_daily (day, received, pending, accepted, preparing, dispatched, completed, cancelled, revenue_cents, drink_completed, pix_completed, card_completed) VALUES (date(NEW.created_at, '-3 hours'), 0, (((NEW.status = 'pending')) - ((OLD.status = 'pending'))), (((NEW.status = 'accepted')) - ((OLD.status = 'accepted'))), (((NEW.status = 'preparing')) - ((OLD.status = 'preparing'))), (((NEW.status = 'dispatched')) - ((OLD.status = 'dispatched'))), (((NEW.status = 'completed')) - ((OLD.status = 'completed'))), (((NEW.status = 'cancelled')) - ((OLD.status = 'cancelled'))), ((CASE WHEN NEW.status = 'completed' THEN NEW.total_cents ELSE 0 END) - (CASE WHEN OLD.status = 'completed' THEN OLD.total_cents ELSE 0 END)), (((NEW.status = 'completed' AND EXISTS (SELECT 1 FROM json_each(NEW.items_json, '$.drinks') WHERE CAST(value AS INTEGER) > 0))) - ((OLD.status = 'completed' AND EXISTS (SELECT 1 FROM json_each(OLD.items_json, '$.drinks') WHERE CAST(value AS INTEGER) > 0)))), (((NEW.status = 'completed' AND json_extract(NEW.customer_json, '$.payment') = 'pix')) - ((OLD.status = 'completed' AND json_extract(OLD.customer_json, '$.payment') = 'pix'))), (((NEW.status = 'completed' AND json_extract(NEW.customer_json, '$.payment') = 'card')) - ((OLD.status = 'completed' AND json_extract(OLD.customer_json, '$.payment') = 'card')))) ON CONFLICT(day) DO UPDATE SET received = received + excluded.received, pending = pending + excluded.pending, accepted = accepted + excluded.accepted, preparing = preparing + excluded.preparing, dispatched = dispatched + excluded.dispatched, completed = completed + excluded.completed, cancelled = cancelled + excluded.cancelled, revenue_cents = revenue_cents + excluded.revenue_cents, drink_completed = drink_completed + excluded.drink_completed, pix_completed = pix_completed + excluded.pix_completed, card_completed = card_completed + excluded.card_completed;
INSERT INTO sales_products_daily(day, kind, product_key, quantity)
SELECT date(OLD.created_at, '-3 hours'), 'pancake', json_object('filling', json_extract(p.value, '$.filling'), 'dough', json_extract(p.value, '$.dough'), 'sauce', json_extract(p.value, '$.sauce'), 'extras', json(COALESCE(json_extract(p.value, '$.extras'), '[]'))), -1 * CAST(json_extract(p.value, '$.qty') AS INTEGER) FROM json_each(OLD.items_json, '$.pancakes') p WHERE OLD.status = 'completed'
ON CONFLICT(day, kind, product_key) DO UPDATE SET quantity = quantity + excluded.quantity;
INSERT INTO sales_products_daily(day, kind, product_key, quantity)
SELECT date(OLD.created_at, '-3 hours'), 'drink', p.key, -1 * CAST(p.value AS INTEGER) FROM json_each(OLD.items_json, '$.drinks') p WHERE OLD.status = 'completed' AND CAST(p.value AS INTEGER) > 0
ON CONFLICT(day, kind, product_key) DO UPDATE SET quantity = quantity + excluded.quantity;
INSERT INTO sales_products_daily(day, kind, product_key, quantity)
SELECT date(NEW.created_at, '-3 hours'), 'pancake', json_object('filling', json_extract(p.value, '$.filling'), 'dough', json_extract(p.value, '$.dough'), 'sauce', json_extract(p.value, '$.sauce'), 'extras', json(COALESCE(json_extract(p.value, '$.extras'), '[]'))), 1 * CAST(json_extract(p.value, '$.qty') AS INTEGER) FROM json_each(NEW.items_json, '$.pancakes') p WHERE NEW.status = 'completed'
ON CONFLICT(day, kind, product_key) DO UPDATE SET quantity = quantity + excluded.quantity;
INSERT INTO sales_products_daily(day, kind, product_key, quantity)
SELECT date(NEW.created_at, '-3 hours'), 'drink', p.key, 1 * CAST(p.value AS INTEGER) FROM json_each(NEW.items_json, '$.drinks') p WHERE NEW.status = 'completed' AND CAST(p.value AS INTEGER) > 0
ON CONFLICT(day, kind, product_key) DO UPDATE SET quantity = quantity + excluded.quantity;
END;
